var STAGE6_OUTLINE_PREFIX = "outline_ep";
var STAGE4_EVENT_PREFIX = "event_";

// source/lib/stage6-pipeline.ts
function buildEventBatches(artifacts) {
  const events = artifacts.filter((a) => a.stage === 4 && a.subKey.startsWith(STAGE4_EVENT_PREFIX)).sort((a, b) => {
    const na = parseInt(a.subKey.replace(STAGE4_EVENT_PREFIX, ""), 10) || 0;
    const nb = parseInt(b.subKey.replace(STAGE4_EVENT_PREFIX, ""), 10) || 0;
    return na - nb;
  });
  const batches = [];
  for (const ev of events) {
    const range2 = parseEventEpisodeRange(ev.content);
    if (!range2) continue;
    const num = parseInt(ev.subKey.replace(STAGE4_EVENT_PREFIX, ""), 10) || 0;
    batches.push({
      eventNum: num,
      eventLabel: ev.label || `\u6838\u5FC3\u4E8B\u4EF6 ${num}`,
      eventContent: ev.content,
      fromEp: range2.from,
      toEp: range2.to
    });
  }
  return batches;
}
function findNextBatchIndex(batches, artifacts) {
  const s6 = artifacts.filter(
    (a) => a.stage === 6 && a.subKey.startsWith(STAGE6_OUTLINE_PREFIX)
  );
  function hasFilledOutline(ep) {
    const key = `${STAGE6_OUTLINE_PREFIX}${ep}`;
    const root3 = s6.find((a) => a.subKey === key && !a.parentKey);
    const t = root3?.content?.trim() ?? "";
    if (t.length < 24) return false;
    return /##\s*第\s*\d+\s*集|本集剧情|开头钩子|结尾悬念/u.test(t);
  }
  for (let i = 0; i < batches.length; i++) {
    const batch = batches[i];
    let allCovered = true;
    for (let ep = batch.fromEp; ep <= batch.toEp; ep++) {
      if (!hasFilledOutline(ep)) {
        allCovered = false;
        break;
      }
    }
    if (!allCovered) return i;
  }
  return batches.length;
}
function extractPrevBatchEndHook(artifacts, prevBatchToEp) {
  const key = `${STAGE6_OUTLINE_PREFIX}${prevBatchToEp}`;
  const outline = artifacts.find(
    (a) => a.stage === 6 && a.subKey === key && !a.parentKey
  );
  if (!outline?.content?.trim()) return "";
  const hookMatch = outline.content.match(/结尾悬念[：:]\s*([\s\S]*?)(?=\n(?:开头钩子|本集剧情|∆|---|$)|\s*$)/);
  if (hookMatch?.[1]?.trim()) {
    return hookMatch[1].trim().slice(0, 300);
  }
  const text = outline.content.trim();
  return text.slice(Math.max(0, text.length - 200));
}
function buildOutlineBatchUserMessage(batch, totalEpisodes, prevBatchEndHook) {
  const parts = [
    `[\u81EA\u52A8\u6D41\u6C34\u7EBF] \u8BF7\u4E25\u683C\u670D\u4ECE\u3010\u9879\u76EE\u4E0A\u4E0B\u6587\u3011\u4E0E\u9879\u76EE\u300C\u7CFB\u5217\u5723\u7ECF\u300D\u6587\u6863\uFF0C`,
    `\u6309 \`Episode Outline Template.md\` \u6A21\u677F\uFF0C\u8F93\u51FA\u7B2C ${batch.fromEp} \u96C6\u81F3\u7B2C ${batch.toEp} \u96C6\u7684\u5206\u96C6\u5927\u7EB2\u3002`,
    `

\u672C\u6279\u6B21\u5BF9\u5E94\u300C${batch.eventLabel}\u300D\uFF08\u7B2C${batch.fromEp}\u96C6 ~ \u7B2C${batch.toEp}\u96C6\uFF09\uFF0C\u4EE5\u4E0B\u662F\u8BE5\u4E8B\u4EF6\u7684\u5B8C\u6574\u5185\u5BB9\uFF0C\u8BF7\u4E25\u683C\u636E\u6B64\u5206\u914D\u5404\u96C6\u5267\u60C5\uFF1A`,
    `

---\u4E8B\u4EF6\u5F00\u59CB---
${batch.eventContent.trim()}
---\u4E8B\u4EF6\u7ED3\u675F---`,
    `

\u786C\u89C4\u5219\uFF1A`,
    `\u2460 \u6BCF\u96C6\u72EC\u7ACB \`## \u7B2CN\u96C6\` \u5757\uFF0C\u7981\u6B62\u5408\u5E76\u96C6\u6570`,
    `\u2461 \u5168\u6587 @\u5F15\u7528\uFF0C\u4E0E\u8BBE\u5B9A\u96C6\u4E00\u5B57\u4E0D\u5DEE`,
    `\u2462\u300C\u672C\u96C6\u5267\u60C5\u300D\u987B\u5B8C\u6574\u6982\u62EC\u672C\u96C6\u6838\u5FC3\u4E8B\u4EF6\u4E0E\u5173\u7CFB\u53D8\u5316\uFF08\u81F3\u5C11 3-5 \u53E5\uFF09`,
    `\u2463 \u6BCF\u96C6\u95F4\u7528 \`---\` \u5206\u9694`,
    `\u2464 \u6BCF\u96C6\u5185\u5404\u5B57\u6BB5\u95F4\u987B\u65AD\u884C`,
    `\u2465 \u672C\u6279\u6240\u6709\u96C6\u7684\u5267\u60C5\u5FC5\u987B\u5B8C\u5168\u56F4\u7ED5\u4E0A\u8FF0\u4E8B\u4EF6\u5C55\u5F00\uFF0C\u7981\u6B62\u63D0\u524D\u6D88\u8017\u540E\u7EED\u4E8B\u4EF6\u7684\u5267\u60C5`
  ];
  if (prevBatchEndHook) {
    parts.push(`
\u4E0A\u4E00\u6279\u6700\u540E\u4E00\u96C6\uFF08\u7B2C ${batch.fromEp - 1} \u96C6\uFF09\u7ED3\u5C3E\u60AC\u5FF5\uFF1A${prevBatchEndHook}`);
    parts.push(`\u8BF7\u786E\u4FDD\u672C\u6279\u5927\u7EB2\u4E0E\u4E0A\u4E00\u6279\u8854\u63A5\u3002`);
  }
  if (batch.fromEp === 1) {
    parts.push(`
\u8FD9\u662F\u5168\u5267\u5F00\u7BC7\uFF0C\u987B\u5EFA\u7ACB\u89D2\u8272\u5173\u7CFB\u4E0E\u6838\u5FC3\u51B2\u7A81\u3002`);
  }
  if (batch.toEp === totalEpisodes) {
    parts.push(`
\u672C\u6279\u5305\u542B\u6700\u540E\u4E00\u96C6\uFF0C\u987B\u5B8C\u6210\u60C5\u7EEA\u5151\u73B0\u4E0E\u7ED3\u5C40\u3002`);
  }
  parts.push(`
\u4EC5\u8F93\u51FA\u7B2C ${batch.fromEp}~${batch.toEp} \u96C6\uFF0C\u7981\u6B62\u8F93\u51FA\u5176\u4ED6\u96C6\u3002`);
  parts.push(`\u5168\u5267\u5171 ${totalEpisodes} \u96C6\u3002`);
  return parts.join("");
}

// source/lib/stage-detect.ts
var STAGE_PATTERNS = [
  // STAGE 5 (设定集) — ∆人物 / ∆物品 / ∆场景（最高优先：与其他阶段无歧义）
  [5, /(?:^|\n)##?\s*∆(?:人物|物品|场景)/],
  [5, /(?:^|\n)##?\s*设定集/],
  // STAGE 7 (分集剧本) — 新格式信号须在 STAGE 6「本集剧情：」类规则之前
  [7, /(?:^|\n)###\s*场次\s*\d+/],
  [7, /(?:^|\n)\s*本集剧情核心\s*[：:]/],
  [7, /(?:^|\n)\s*∆出场人物\s*[：:]/],
  [7, /(?:^|\n)---\s*\n\s*正文\s*[：:]/],
  [7, /(?:^|\n)##?\s*第\s*\[集数\]\s*集/],
  // STAGE 6 (分集大纲) — 独有 开头钩子/本集剧情（精确短语，避免误伤「本集剧情摘要」）
  // 注：`本集剧情` 后须接非汉字/非字母，防止匹配「本集剧情摘要」等 Stage 7 标题
  [6, /(?:^|\n)###?\s*(?:开头钩子|本集概述|结尾悬念)/],
  [6, /(?:^|\n)###?\s*本集剧情(?!摘要|[a-zA-Z\u4e00-\u9fff])/],
  [6, /(?:^|\n)(?:开头钩子|本集概述|结尾悬念)[：:]/],
  [6, /(?:^|\n)本集剧情(?!摘要|[a-zA-Z\u4e00-\u9fff])[：:]/],
  [6, /(?:^|\n)##?\s*分集大纲/],
  // STAGE 7 裸 `## 第N集` 兜底（在 STAGE 6 之后，避免大纲的集标题误触）
  [7, /(?:^|\n)##?\s*第\s*\d+\s*集/],
  /**
   * STAGE 1 须在 2/3/4 之前：同条回复里常同时出现「## 一句话梗概」与「## 第一幕」式小节，
   * 若先匹配三幕，会误判为 STAGE 3，导致一句话梗概无法按 STAGE 1 解析落库。
   */
  [1, /(?:^|\n)\s*一句话梗概\s*[：:]/],
  [1, /(?:^|\n)##?\s*(?:一句话梗概|完整大纲|详细剧情梗概)/],
  [4, /(?:^|\n)##?\s*核心事件\s*\d/],
  /** 幕标题后须为行尾、冒号类或（，避免「## 第一幕的情感铺垫」等 STAGE1 叙述误判 */
  [3, /(?:^|\n)##\s*第[一二三]幕(?:\s|$|[：:（(])/],
  [2, /(?:^|\n)##?\s*角色[一二三四五六七八九十\d]+[：:]/]
];
function lineDeclaresStage(content, stageNum) {
  const re = new RegExp(
    `^\\s*(?:#{1,2}\\s+)?(?:\\*{0,2})?(?:\u3010\\[\uFF3B]\\s*)?STAGE\\s*${stageNum}\\b`,
    "m"
  );
  return content.split(/\r?\n/).some((line) => re.test(line));
}
function cleanThinkBlocks(content) {
  return stripThinkingBlocks(content);
}
function detectStageFromContent(content) {
  const cleaned = cleanThinkBlocks(content);
  for (const [stage2, re] of STAGE_PATTERNS) {
    if (re.test(cleaned)) return stage2;
  }
  for (let s = 7; s >= 1; s--) {
    if (lineDeclaresStage(cleaned, s)) return s;
  }
  return 0;
}
function detectStage(messages) {
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    if (msg.role !== "assistant") continue;
    const result2 = detectStageFromContent(msg.content);
    if (result2 > 0) return result2;
  }
  return 0;
}

